import { useUserMetadata } from '../../services/userMetadata/useUserMetadata';
import { useAuthenticationService } from '../useService/UseService';

const defaultLanguage = localStorage.getItem('language') ?? 'en-US';

const availableLanguages = {
  en: 'en-US',
  es: 'es-419',
  pt: 'pt-BR',
  id: 'id-ID',
  ko: 'ko-KR',
  fr: 'fr-FR',
  vi: 'vi-VN',
  'en-GB': 'en-GB'
};

const PREFERRED_LANGUAGE_CACHE_KEY = 'preferredLanguage';

export type PrefferedLanguageInstance = {
  preferredLanguage: string | undefined;
  defaultLanguage: string;
  isLoading: boolean;
  hasError: boolean;
};

export function usePreferredLanguageV2(): PrefferedLanguageInstance {
  const { data, isLoading, hasError } = useUserMetadata();
  const { language } = useAuthenticationService().getUserCountryAndLanguage();

  const userDefaultLanguage =
    availableLanguages[language] ?? availableLanguages[language?.split('-')[0]] ?? defaultLanguage;

  const preferredLanguage = data?.profile?.preferredLanguage;

  if (preferredLanguage) {
    localStorage.setItem(PREFERRED_LANGUAGE_CACHE_KEY, preferredLanguage);
  }

  const storedLanguage = localStorage.getItem(PREFERRED_LANGUAGE_CACHE_KEY);
  const cachedLanguage =
    storedLanguage && availableLanguages[storedLanguage] ? storedLanguage : null;
  const effectivePreferredLanguage = preferredLanguage ?? cachedLanguage ?? undefined;

  return {
    preferredLanguage: effectivePreferredLanguage,
    defaultLanguage: userDefaultLanguage,
    isLoading,
    hasError
  };
}
