import { LocaleModule, LocaleRequireContext } from './types';

export function collectLocalesFromContext(
  context: LocaleRequireContext
): Record<string, Record<string, unknown>> {
  const messages: Record<string, Record<string, unknown>> = {};

  context.keys().forEach((fileName: string) => {
    const language = fileName.replace(/^\.\/|\.(?:ts|json)$/g, '');
    if (language === 'applanga') return;

    const mod: LocaleModule = context(fileName);
    messages[language] = (mod.default ?? mod) as Record<string, unknown>;
  });

  return messages;
}
