export const stripTranslationPrefix = (
  messages: Record<string, string>,
  translationPrefix: string
): Record<string, string> => {
  const prefixWithDot = `${translationPrefix}.`;
  const stripped: Record<string, string> = {};

  Object.keys(messages).forEach((key) => {
    const newKey = key.startsWith(prefixWithDot) ? key.slice(prefixWithDot.length) : key;
    stripped[newKey] = messages[key];
  });

  return stripped;
};
