import axios from 'axios';
import useSwr from 'swr';
import API_URLS from '../../constants/API_URLS';
import { USERS_LIST_MAX_IDS } from '@constants/API_LIMITS';
import { useAuthenticationService } from '@hooks/useService/UseService';
import {
  IdentityUserAccount,
  GetUserDataByAccountIdsResponse,
  UseGetUserNamesOptions
} from '@hooks/useGetUserNames/useGetUserNames.types';
import { OnError } from '@hooks/useGetAuditLogs/useGetAuditLogs.types';

const initialAxios = axios.create();
const authentication = useAuthenticationService();
const { user_country: userCountry } = authentication.getUserCountryAndLanguage();

authentication.enhancedAxios(initialAxios, {
  headers: [
    {
      country: userCountry ?? ''
    }
  ]
});

const DEFAULT_APP_NAME = 'unknown';

/** BFF: GET /identity/user-accounts — accepts 1–50 user IDs via query param ids */
const PATH_IDENTITY_USER_ACCOUNTS = API_URLS.IDENTITY_USER_ACCOUNTS;

function getDisplayName(user: IdentityUserAccount): string {
  if (user.displayName) {
    return user.displayName;
  }
  const full = [user.givenName, user.surname].filter(Boolean).join(' ').trim();
  if (full) {
    return full;
  }
  if (user.email) {
    return user.email;
  }
  return user.id;
}

function buildMapFromUserAccounts(users: Array<IdentityUserAccount>): Map<string, string> {
  const map = new Map<string, string>();
  /* istanbul ignore next: defensive; fetcher always passes array */
  const list = Array.isArray(users) ? users : [];
  list.forEach(user => {
    if (user?.id) {
      map.set(user.id, getDisplayName(user));
    }
  });
  return map;
}

const fetcher = (onError?: OnError) => {
  return (apiPath: string) => {
    return initialAxios
      .get<GetUserDataByAccountIdsResponse>(apiPath)
      .then(res => {
        const data = res.data;
        /* istanbul ignore next: defensive; BFF returns array of user accounts */
        const users = Array.isArray(data) ? data : [];
        return buildMapFromUserAccounts(users);
      })
      .catch(error => {
        if (error.response && typeof onError === 'function') {
          onError(error.response.data);
        }

        throw error;
      });
  };
};

/**
 * Fetches user display names by IDs (e.g. for audit log "doneBy" resolution).
 * Uses BFF GET /identity/user-accounts with query params appName and ids (1–50 userIds).
 */
export function useGetUserNames(
  userIds: Array<string>,
  shouldFetch: boolean = true,
  onError?: OnError,
  options?: UseGetUserNamesOptions
) {
  const appName = options?.appName ?? DEFAULT_APP_NAME;
  const uniqueIds = [...new Set(userIds)].filter(Boolean);
  const truncated =
    uniqueIds.length > USERS_LIST_MAX_IDS ? uniqueIds.slice(0, USERS_LIST_MAX_IDS) : uniqueIds;

  const apiPath =
    truncated.length > 0
      ? `${PATH_IDENTITY_USER_ACCOUNTS}?ids=${truncated.join(',')}&appName=${encodeURIComponent(appName)}&ignoreCountry=true`
      : null;

  const { data, error, isValidating } = useSwr(
    shouldFetch && apiPath ? apiPath : null,
    fetcher(onError),
    {
      revalidateOnFocus: false,
      revalidateOnReconnect: false,
      errorRetryCount: 2
    }
  );

  return {
    data: data ?? undefined,
    isLoading: isValidating,
    hasError: Boolean(error),
    error
  };
}
