import { createEvent, createStore } from 'effector';
import { HubTheme } from '../../hooks/useHubTheme/helpers';

export const setTheme = createEvent<HubTheme>('setTheme');
export const restoreToDefault = createEvent('restoreToDefault');

export const themeStore = createStore<HubTheme | null>(null)
  .on(setTheme, (_, theme) => theme)
  .reset(restoreToDefault);
