import axios from 'axios';
import { useMemo } from 'react';
import useSwr from 'swr';
import API_URLS from '../../constants/API_URLS';
import { flattenObject } from '../../utils/flattenObject';
import { useAuthenticationService } from '../useService/UseService';
import { TranslationMessages, UseTranslationParams, UseTranslationReturn } from './types';

// Helper to check if the data is a valid translation object
const isValidTranslationObject = (data: any): data is TranslationMessages => {
  if (!data) return false;
  if (Array.isArray(data)) return false;
  if (typeof data === 'string') return false; // Reject any string (including HTML)
  if (typeof data !== 'object') return false;
  return true;
};

export const useTranslation = ({
  mfe,
  locale,
  fallbackMessages,
  enableBFF = true
}: UseTranslationParams): UseTranslationReturn => {
  const authentication = useAuthenticationService();

  const axiosInstance = useMemo(() => {
    const instance = axios.create();
    authentication.enhancedAxios(instance);
    return instance;
  }, [authentication]);

  const fetcher = (url: string) =>
    axiosInstance
      .get<TranslationMessages>(url)
      .then(res => {
        if (isValidTranslationObject(res.data)) {
          return res.data;
        }
        throw new Error('Invalid translation format received from server.');
      })
      .catch(async error => {
        // Temporary retry rule: if es-419 is not found, try with es-ES
        if (locale === 'es-419' && mfe) {
          try {
            const fallbackUrl = `${API_URLS.TRANSLATIONS}/${mfe}/es-ES`;
            const fallbackRes = await axiosInstance.get<TranslationMessages>(fallbackUrl);
            if (isValidTranslationObject(fallbackRes.data)) {
              return fallbackRes.data;
            }
          } catch (fallbackError) {
            // If fallback also fails, throw the original error
          }
        }
        throw error;
      });

  const translationUrl =
    enableBFF && mfe && locale ? `${API_URLS.TRANSLATIONS}/${mfe}/${locale}` : null;

  const { data, error, isValidating } = useSwr(translationUrl, fetcher, {
    dedupingInterval: 3600000, // 1 hour
    revalidateOnFocus: false,
    revalidateOnReconnect: false,
    revalidateIfStale: false,
    shouldRetryOnError: false
  });

  const isSuccessful = Boolean(enableBFF && !error && data && isValidTranslationObject(data));

  const messages = useMemo(() => {
    // If we have valid data from the server, use it
    if (isSuccessful && data) {
      return flattenObject(data);
    }
    // Otherwise use fallback (flatten if needed)
    if (!fallbackMessages) return {};
    // Check if already flattened (all values are strings)
    const isFlattened = Object.values(fallbackMessages).every(v => typeof v === 'string');
    return isFlattened
      ? (fallbackMessages as Record<string, string>)
      : flattenObject(fallbackMessages);
  }, [isSuccessful, data, fallbackMessages]);

  const isLoading = enableBFF && isValidating && !data && !error;

  return {
    messages,
    isLoading,
    hasError: Boolean(error),
    error,
    isSuccessful
  };
};
